import { describe, expect, test } from "vitest";
import {
  HOOK_NAMES,
  hookCommand,
  hookScript,
} from "../../../src/core/hooks/index.js";

const specExample = `#!/bin/sh
# metafab:start
# Generated by metafab build 1.0.0. Set git-hooks: false in .factory/metafab.yaml to remove.
cd "$(git rev-parse --show-toplevel)/." 2>/dev/null || exit 0
[ -d .factory ] || exit 0
if [ -x node_modules/.bin/metafab ]; then node_modules/.bin/metafab build
elif main=$(git -c core.quotePath=false worktree list --porcelain 2>/dev/null | sed -n '1{s/^worktree //;h;d;};/^bare$/q;g;p;q') && [ -n "$main" ] && [ -x "$main/./node_modules/.bin/metafab" ]; then "$main/./node_modules/.bin/metafab" build
elif command -v metafab >/dev/null 2>&1; then metafab build
else npx --yes @seasb/metafab@1.0.0 build
fi || echo "metafab: build failed. Run metafab build." >&2
exit 0
# metafab:end
`;

describe("hookScript", () => {
  test("post-merge at the repository root equals the spec example exactly", () => {
    expect(hookScript("post-merge", ".", "1.0.0")).toBe(specExample);
  });

  test("snapshot per hook", () => {
    for (const hook of HOOK_NAMES) {
      expect(hookScript(hook, ".", "1.2.3")).toMatchSnapshot(hook);
    }
  });

  test("post-checkout exits unless its third argument is 1", () => {
    const script = hookScript("post-checkout", ".", "1.0.0");

    expect(script).toContain('[ "$3" = "1" ] || exit 0');
    expect(script.indexOf('[ "$3" = "1" ]')).toBeLessThan(
      script.indexOf("cd \"$(git rev-parse --show-toplevel)"),
    );
    expect(hookScript("post-merge", ".", "1.0.0")).not.toContain('"$3"');
  });

  test("post-rewrite exits unless its first argument is rebase", () => {
    const script = hookScript("post-rewrite", ".", "1.0.0");

    expect(script).toContain('[ "$1" = "rebase" ] || exit 0');
    expect(script.indexOf('[ "$1" = "rebase" ]')).toBeLessThan(
      script.indexOf("cd \"$(git rev-parse --show-toplevel)"),
    );
    expect(hookScript("post-merge", ".", "1.0.0")).not.toContain('"$1"');
  });

  test("quotes the factory directory", () => {
    const script = hookScript("post-merge", "packages/my app", "1.0.0");
    const command = hookCommand("packages/my app", "1.0.0");
    const mainCli = '[ -x "$main/packages/my app/node_modules/.bin/metafab" ]';

    expect(script).toContain('cd "$(git rev-parse --show-toplevel)/packages/my app" 2>/dev/null || exit 0');
    expect(command).toContain('(cd "$(git rev-parse --show-toplevel)/packages/my app" &&');
    expect(script).toContain(mainCli);
    expect(command).toContain(mainCli);
  });

  test("includes the CLI version that wrote it", () => {
    expect(hookScript("post-merge", ".", "9.8.7")).toContain(
      "@seasb/metafab@9.8.7 build",
    );
    expect(hookScript("post-merge", ".", "9.8.7")).toContain(
      "# Generated by metafab build 9.8.7.",
    );
  });

  test("is POSIX sh with the ownership marker on its own line", () => {
    const script = hookScript("post-merge", ".", "1.0.0");
    const lines = script.split("\n");

    expect(lines[0]).toBe("#!/bin/sh");
    expect(lines).toContain("# metafab:start");
    expect(lines).toContain("# metafab:end");
    expect(script).toContain('echo "metafab: build failed. Run metafab build." >&2');
    expect(script.trimEnd().endsWith("exit 0\n# metafab:end")).toBe(true);
  });
});

describe("hookCommand", () => {
  test("is the single-line form from the plan", () => {
    expect(hookCommand(".", "1.0.0")).toBe(
      `(cd "$(git rev-parse --show-toplevel)/." && if [ -x node_modules/.bin/metafab ]; then node_modules/.bin/metafab build; elif main=$(git -c core.quotePath=false worktree list --porcelain 2>/dev/null | sed -n '1{s/^worktree //;h;d;};/^bare$/q;g;p;q') && [ -n "$main" ] && [ -x "$main/./node_modules/.bin/metafab" ]; then "$main/./node_modules/.bin/metafab" build; elif command -v metafab >/dev/null 2>&1; then metafab build; else npx --yes @seasb/metafab@1.0.0 build; fi) || true`,
    );
  });

  test("resolves the CLI in the same order and at the same version as the script", () => {
    const script = hookScript("post-merge", ".", "3.4.5");
    const command = hookCommand(".", "3.4.5");

    const steps = [
      "if [ -x node_modules/.bin/metafab ]; then node_modules/.bin/metafab build",
      `elif main=$(git -c core.quotePath=false worktree list --porcelain 2>/dev/null | sed -n '1{s/^worktree //;h;d;};/^bare$/q;g;p;q') && [ -n "$main" ] && [ -x "$main/./node_modules/.bin/metafab" ]; then "$main/./node_modules/.bin/metafab" build`,
      "elif command -v metafab >/dev/null 2>&1; then metafab build",
      "else npx --yes @seasb/metafab@3.4.5 build",
    ];

    for (const step of steps) {
      expect(script).toContain(step);
      expect(command).toContain(step);
    }

    for (let index = 1; index < steps.length; index += 1) {
      expect(script.indexOf(steps[index - 1]!)).toBeLessThan(script.indexOf(steps[index]!));
      expect(command.indexOf(steps[index - 1]!)).toBeLessThan(command.indexOf(steps[index]!));
    }
  });
});
